-- ============================================================
-- f0_ingredient_codes: 식약처 성분코드 테이블 (12,263개)
-- 담당: f0 (경아)
-- 생성일: 2026-04-17
-- ============================================================

CREATE TABLE IF NOT EXISTS f0_ingredient_codes (
    id           BIGSERIAL PRIMARY KEY,
    code         TEXT NOT NULL UNIQUE,
    name_ko      TEXT NOT NULL,
    name_en      TEXT,
    category     TEXT,
    code_prefix  CHAR(1),
    updated_at   TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_f0_ingredient_codes_name_ko
    ON f0_ingredient_codes (name_ko);

CREATE INDEX IF NOT EXISTS idx_f0_ingredient_codes_code_prefix
    ON f0_ingredient_codes (code_prefix);

CREATE INDEX IF NOT EXISTS idx_f0_ingredient_codes_category
    ON f0_ingredient_codes (category);

-- 전문 검색용 트리그램 인덱스
CREATE INDEX IF NOT EXISTS idx_f0_ingredient_codes_name_trgm
    ON f0_ingredient_codes USING gin (name_ko gin_trgm_ops);

